"""Mitología de Euskal Herria para la mesa: criaturas para el bestiario y especies jugables.

Es material propio de esta app (no sale de ningún manual), inspirado en las leyendas recogidas por
José Miguel de Barandiaran y en la tradición oral. Las cifras siguen las reglas oficiales para que
encajen en la partida:
- Criaturas: la tabla «Estadísticas de monstruo por valor de desafío» de la Guía del Dungeon Master
  (CA, PG, bonificador de ataque, daño por asalto y CD para cada VD). tests/test_server.py calcula el
  VD de cada una con ese método y comprueba que coincide con el declarado (±1).
- Especies: el mismo «presupuesto» que las especies del Manual del Jugador 2024 (un rasgo fuerte,
  dos o tres menores y magia que se desbloquea en los niveles 3 y 5).

Campos solo para el cálculo del VD: «per_turn» (veces que se usa un ataque por asalto, contando
multiataque y acciones legendarias), «area» (la acción con salvación alcanza a varias criaturas),
«resist» (resistencia a daño contundente, cortante y perforante) y «lr» (resistencia legendaria).
"""

SOURCE = "Mitología vasca"


def _atk(name, bonus, damage, notes, per_turn=0):
    return {"name": name, "bonus": bonus, "damage": damage, "notes": notes, "per_turn": per_turn}


def _save(name, save, damage, notes, area=True):
    return {"name": name, "bonus": "", "save": save, "damage": damage, "notes": notes, "area": area}


def _c(name, eu, cr, size, creature, alignment, ac, hp, hp_dice, speed, init, abil, saves, attacks, traits, **extra):
    return {
        "name": name, "eu": eu, "source": SOURCE, "cr": cr, "ac": ac, "hp": hp, "hpDice": hp_dice, "speed": speed,
        "size": size, "creature": creature, "alignment": alignment, "init": init, "saves": saves,
        "abilities": dict(zip(("fue", "des", "con", "int", "sab", "car"), abil)),
        "attacks": attacks, "traits": "\n".join(traits), **extra,
    }


